let hφ : φ.ker = 0 :=
  by
    rw [ker_eq_zero];
    intro v;
    assume h0 : φ v = 0;
    have hlin : LinearIndepOn K (fun i ↦ v i) ι :=
      by
        apply Module.exists_dual_forall_apply_eq_one;
        exact ⟨f, fun i ↦ (f i) (v i)⟩;
        intros i;
        exact (f i) (v i);
        exact (fun i ↦ (f i) (v i)) i;
        assumption;
    exact hlin;

let hφ_inj : Function.Injective φ :=
  by
    intro v w;
    assume h0 : φ v = φ w;
    have h1 : φ (v - w) = 0 :=
      by rw [h0]; rw [sub_eq_zero]; rw [add_left_neg]; rw [zero_add];
    exact (hφ h1).symm;

